CREATE DATABASE b6_boundary_main WITH (max_data_region_group_num=2);
USE b6_boundary_main;CREATE TABLE telemetry(device_id STRING TAG,s1 INT64 FIELD,s2 DOUBLE FIELD);
FLUSH;
CREATE DATABASE b6_boundary_singlepart WITH (max_data_region_group_num=2);
USE b6_boundary_singlepart;CREATE TABLE telemetry(device_id STRING TAG,s1 INT64 FIELD);
FLUSH;
CREATE DATABASE b6_boundary_ties WITH (max_data_region_group_num=2);
USE b6_boundary_ties;CREATE TABLE telemetry(group_tag STRING TAG,variant STRING TAG,s1 INT64 FIELD);
FLUSH;
CREATE DATABASE b6_boundary_diff WITH (max_data_region_group_num=1);
USE b6_boundary_diff;CREATE TABLE telemetry(device_id STRING TAG,s1 INT64 FIELD);
FLUSH;
CREATE DATABASE b6_boundary_skew WITH (max_data_region_group_num=2);
USE b6_boundary_skew;CREATE TABLE telemetry(device_id STRING TAG,s1 INT64 FIELD,payload STRING FIELD);
FLUSH;
